[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "{% set company = frappe.get_doc("Company", doc.company) if doc.company else None %}
{% macro addr_block(address_name) -%}
  {%- if address_name -%}
    {%- set a = frappe.get_doc("Address", address_name) -%}
    <div class="addr">
      <div class="strong">{{ a.address_title or "" }}</div>
      {% if a.address_line1 %}<div>{{ a.address_line1 }}</div>{% endif %}
      {% if a.address_line2 %}<div>{{ a.address_line2 }}</div>{% endif %}
      <div>
        {{ a.city or "" }}{% if a.city and a.state %}, {% endif %}{{ a.state or "" }}
        {% if a.pincode %} {{ a.pincode }}{% endif %}
      </div>
      {% if a.country %}<div>{{ a.country }}</div>{% endif %}
      {% if a.phone %}<div>Phone: {{ a.phone }}</div>{% endif %}
      {% if a.mobile_no %}<div>Mobile Phone: {{ a.mobile_no }}</div>{% endif %}
    </div>
  {%- else -%}
    <div class="muted">—</div>
  {%- endif -%}
{%- endmacro %}

{% set sales_rep_email = "" %}
{% set sales_rep_phone = "" %}
{% if doc.sales_team and doc.sales_team|length %}
  {% set sp_name = doc.sales_team[0].sales_person %}
  {% set emp_name = frappe.db.get_value("Employee", {"employee_name": sp_name}, "name") %}
  {% if emp_name %}
    {% set emp = frappe.get_doc("Employee", emp_name) %}
    {% set sales_rep_email = emp.user_id or emp.company_email or emp.personal_email or "" %}
    {% set sales_rep_phone = emp.mobile or emp.cell_number or emp.phone_number or "" %}
  {% endif %}
{% endif %}

<style>
  .pf-header, .pf-header table, .pf-header tr, .pf-header td, .pf-header th {
    border: 0 !important;
    background: transparent !important;
    box-shadow: none !important;
    outline: none !important;
  }
  .pf-header * { box-sizing: border-box; }
  .pf-header {
    width: 100%;
    font-family: Arial, sans-serif;
    color: #111;
    font-size: 12px;
    line-height: 1.3;
  }
  .pf-header table { width: 100%; border-collapse: collapse; margin: 0; }
  .print-format .pf-header td { padding: 0 !important; vertical-align: top !important; }
  .print-format .pf-header .brand td { vertical-align: middle !important; }
  .pf-header .brand { margin-bottom: 12px; }
  .pf-header .brand .logo-cell { width: 1%; padding-right: 14px !important; }
  .pf-header .logo { max-height: 60px; }
  .pf-header .cname { font-size: 32px; font-weight: 700; line-height: 1.1; }
  .pf-header .ctag { font-size: 11px; font-weight: 700; margin-top: 2px; }

  .pf-header .info { table-layout: fixed; }
  .print-format .pf-header .info .addr-col { padding-right: 12px !important; }
  .pf-header .title { font-weight: 700; font-size: 13px; margin-bottom: 3px; }
  .pf-header .strong { font-weight: 700; }
  .pf-header .muted { color: #666; }

  .print-format .pf-header .meta td { padding: 2px 0 !important; line-height: 1.3; }
  .pf-header .meta .m-lbl { width: 122px; font-weight: 700; white-space: nowrap; }
  .pf-header .meta .m-sep { width: 14px; text-align: center; }
  .pf-header .meta .m-val { word-wrap: break-word; overflow-wrap: anywhere; }

  .pf-header .email { margin-top: 12px; font-size: 13px; }
  .pf-header .email .lbltxt { font-weight: 700; }

  /* Hide Frappe's global "DRAFT" banner on this format */
  .print-format [document-status="draft"] { display: none !important; }
</style>

<div class="pf-header">
  <table class="brand">
    <tr>
      {% if company and company.company_logo %}
      <td class="logo-cell"><img class="logo" src="{{ company.company_logo }}" /></td>
      {% endif %}
      <td>
        <div class="cname">{{ company.company_name if company else (doc.company or "") }}</div>
        <div class="ctag">{{ company.company_description or "GENERAL MERCHANDISE" }}</div>
      </td>
    </tr>
  </table>

  <table class="info">
    <colgroup>
      <col style="width:28%;" />
      <col style="width:28%;" />
      <col style="width:44%;" />
    </colgroup>
    <tr>
      <td class="addr-col">
        <div class="title">Billing Information:</div>
        {{ addr_block(doc.customer_address) }}
      </td>
      <td class="addr-col">
        <div class="title">Shipping Information:</div>
        {{ addr_block(doc.shipping_address_name) }}
      </td>
      <td>
        <table class="meta">
          <tbody>
            <tr><td class="m-lbl">Order #</td><td class="m-sep">:</td><td class="m-val strong">{{ doc.name }}</td></tr>
            <tr><td class="m-lbl">Order Date</td><td class="m-sep">:</td><td class="m-val">{{ frappe.utils.formatdate(doc.posting_date or doc.transaction_date) }}</td></tr>
            <tr><td class="m-lbl">Sales Rep</td><td class="m-sep">:</td><td class="m-val">{% if doc.sales_team and doc.sales_team|length %}{{ doc.sales_team[0].sales_person }}{% else %}—{% endif %}</td></tr>
            <tr><td class="m-lbl">Sales Rep Phone</td><td class="m-sep">:</td><td class="m-val">{{ sales_rep_phone or "—" }}</td></tr>
            <tr><td class="m-lbl">Sales Rep Email</td><td class="m-sep">:</td><td class="m-val">{{ sales_rep_email or "—" }}</td></tr>
            <tr><td class="m-lbl">Processed By</td><td class="m-sep">:</td><td class="m-val">{% if doc.sales_team and doc.sales_team|length %}{{ doc.sales_team[0].sales_person }}{% else %}—{% endif %}</td></tr>
            <tr><td class="m-lbl">Account #</td><td class="m-sep">:</td><td class="m-val">{{ doc.get("customer_account_number") or doc.get("account_no") or "—" }}</td></tr>
            {% if doc.docstatus != 0 %}
            <tr><td class="m-lbl">Status</td><td class="m-sep">:</td><td class="m-val">{{ doc.status or "—" }}</td></tr>
            {% endif %}
            <tr><td class="m-lbl">Order Type</td><td class="m-sep">:</td><td class="m-val">{{ doc.get("order_type") or "—" }}</td></tr>
          </tbody>
        </table>
      </td>
    </tr>
  </table>

  <div class="email">
    <span class="lbltxt">Email Address:</span>
    {% if doc.custom_customer_email %}
      <a href="mailto:{{ doc.custom_customer_email }}">{{ doc.custom_customer_email }}</a>
    {% else %}<span class="muted">—</span>{% endif %}
  </div>
</div>
"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "
{% macro money(val) -%}
  {{ frappe.utils.fmt_money(val or 0, currency=doc.currency) }}
{%- endmacro %}

{# optional: detect shipping/handling rows from taxes table #}
{% set shipping_amt = 0 %}
{% set handling_amt = 0 %}
{% if doc.taxes %}
  {% for t in doc.taxes %}
    {% set x = ((t.description or t.account_head or "")|lower) %}
    {% if "shipping" in x or "pickup" in x %}
      {% set shipping_amt = shipping_amt + (t.tax_amount or 0) %}
    {% elif "handling" in x %}
      {% set handling_amt = handling_amt + (t.tax_amount or 0) %}
    {% endif %}
  {% endfor %}
{% endif %}

<style>
  .pf-items { font-family: Arial, sans-serif; font-size: 12px; color: #111; line-height: 1.3; }
  .pf-items table.items { width: 100%; border-collapse: collapse; margin-top: 10px; table-layout: fixed; }
  .pf-items table.items thead { display: table-header-group; } /* repeats on each page */
  .pf-items table.items tr { page-break-inside: avoid; break-inside: avoid; }
  .print-format .pf-items table.items th,
  .print-format .pf-items table.items td { padding: 6px 5px !important; vertical-align: top !important; }
  .pf-items table.items th { font-weight: 700; color: #777; border-bottom: 1px solid #bbb; }
  .pf-items table.items td { border-bottom: 1px solid #eee; }

  .pf-items .center { text-align: center; }
  .pf-items .num { text-align: right; white-space: nowrap; }
  .pf-items .sku { font-weight: 700; margin-top: 4px; }
  .pf-items .pname { font-weight: 700; word-wrap: break-word; overflow-wrap: break-word; }
  .pf-items .img { width: 44px; height: 44px; border: 1px solid #ddd; object-fit: contain; }

  .print-format .pf-items table.totals { width: 340px; margin: 14px 0 0 auto; border-collapse: collapse; }
  .print-format .pf-items table.totals td { padding: 3px 0 3px 16px !important; border: 0 !important; text-align: right; white-space: nowrap; }
  .pf-items table.totals .grand td { font-weight: 700; padding-top: 6px !important; }

  .pf-items .pm { margin-top: 14px; border-top: 1px solid #bbb; padding-top: 8px; }
  .pf-items .pm .lbltxt { font-weight: 700; }
</style>

<div class="pf-items">

  <!-- Items table -->
  <table class="items">
    <colgroup>
      <col style="width:7%;" />
      <col style="width:12%;" />
      <col />
      <col style="width:7%;" />
      <col style="width:9%;" />
      <col style="width:9%;" />
      <col style="width:11%;" />
      <col style="width:12%;" />
    </colgroup>
    <thead>
      <tr>
        <th class="center">Line#</th>
        <th>Sku</th>
        <th>Product Name</th>
        <th class="center">Case<br>Pack</th>
        <th class="center">Quantity</th>
        <th class="center">Packing</th>
        <th class="num">Price</th>
        <th class="num">Total</th>
      </tr>
    </thead>

    <tbody>
      {% for it in doc.items %}
      <tr>
        <td class="center">{{ loop.index }}</td>
        <td>
          {% if it.image %}
            <img class="img" src="{{ it.image }}">
          {% endif %}
          <div class="sku">{{ it.item_code }}</div>
        </td>
        <td><div class="pname">{{ it.item_name or it.item_code }}</div></td>
        <td class="center">{{ it.get("custom_case_pack") or "" }}</td>
        <td class="center">{{ it.qty or 0 }}</td>
        <td class="center">{{ it.get("packing") or it.get("pack_uom") or it.uom or "" }}</td>
        <td class="num">{{ money(it.rate) }}</td>
        <td class="num">{{ money(it.amount) }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <!-- Totals -->
  <table class="totals">
    <tr><td>Subtotal:</td><td>{{ money(doc.total) }}</td></tr>
    <tr><td>Tax:</td><td>{{ money(doc.total_taxes_and_charges) }}</td></tr>
    {% if shipping_amt %}
    <tr><td>Shipping (Pickup):</td><td>{{ money(shipping_amt) }}</td></tr>
    {% endif %}
    {% if handling_amt %}
    <tr><td>Handling:</td><td>{{ money(handling_amt) }}</td></tr>
    {% endif %}
    <tr class="grand"><td>Grand Total:</td><td>{{ money(doc.grand_total) }}</td></tr>
    {% if doc.advance_paid %}
    <tr><td>Balance:</td><td>{{ money(doc.outstanding_amount) }}</td></tr>
    {% endif %}
  </table>

  <!-- Payment Method -->
  <div class="pm">
    <span class="lbltxt">Payment Method:</span>
    <span>{{ doc.custom_mode_of_payment or doc.payment_terms_template or "—" }}</span>
  </div>

</div>
"}]
